class Solution {
    vector<long long> sums;

    long long dfs(TreeNode* node) {
        if (!node) {
            return 0;
        }
        long long sum = node->val + dfs(node->left) + dfs(node->right);
        sums.push_back(sum);
        return sum;
    }

public:
    bool checkEqualTree(TreeNode* root) {
        if (!root) {
            return false;
        }
        long long total = dfs(root);
        sums.pop_back();
        if (total % 2 != 0) {
            return false;
        }
        return find(sums.begin(), sums.end(), total / 2) != sums.end();
    }
};
